import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matmul_cute(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// C(M,N) = A(M,K) * B(K,N), all row-major.
// Cooperative tiled kernel: each CTA computes a 128x128 tile of C with 256
// threads. A-tiles are staged TRANSPOSED in shared memory and each thread
// owns a contiguous 8x8 sub-tile, so both operand fragments are fetched
// with vectorized float4 shared-memory loads (4 LDS.128 instead of 16
// LDS.32 per k step) and global->smem staging uses vectorized float4
// global loads whenever the row strides allow 16B-aligned accesses.
template <typename T>
__global__ void gemm_nn_kernel(const T* __restrict__ A,
                               const T* __restrict__ B,
                               T* __restrict__ C,
                               int M, int N, int K)
{
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 32;
  constexpr int TM = 8;
  constexpr int TN = 8;
  constexpr int THREADS = (BM / TM) * (BN / TN);  // 256
  constexpr int TX = BN / TN;                     // 16
  constexpr int TY = BM / TM;                     // 16
  // Padded strides keep every smem row 16B aligned (for float4 access)
  // while the +4 skew keeps the staging stores spread over the banks.
  constexpr int SA = BM + 4;  // sA row stride (132), sA is BK x BM
  constexpr int SB = BN + 4;  // sB row stride (132), sB is BK x BN
  const int tid = threadIdx.x;
  const int by  = blockIdx.x;  // M tile index
  const int bx  = blockIdx.y;  // N tile index
  // Global tensors (row-major) via CuTe. Use 64-bit leading strides to be
  // safe with very large outputs.
  Tensor mA = make_tensor(make_gmem_ptr(A),
                          make_shape(M, K),
                          make_stride((int64_t)K, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(B),
                          make_shape(K, N),
                          make_stride((int64_t)N, Int<1>{}));
  Tensor mC = make_tensor(make_gmem_ptr(C),
                          make_shape(M, N),
                          make_stride((int64_t)N, Int<1>{}));
  // sA is stored transposed: sA(k, m) = A-tile(m, k).
  __shared__ __align__(16) T smemA[BK * SA];
  __shared__ __align__(16) T smemB[BK * SB];
  const int m0 = by * BM;
  const int n0 = bx * BN;
  const int warp = tid >> 5;
  const int lane = tid & 31;
  const int wm = warp >> 2;
  const int wn = warp & 3;
  const int lm = lane >> 2;
  const int ln = lane & 3;
  const int row0 = (wm << 6) + (lm << 3);
  const int col0 = (wn << 5) + (ln << 3);
  T acc[TM][TN];
  #pragma unroll
  for (int i = 0; i < TM; ++i)
    #pragma unroll
    for (int j = 0; j < TN; ++j)
      acc[i][j] = T(0);
  // 16B-aligned vectorized global loads require row strides that are
  // multiples of 4 floats.
  const bool kvec = ((K & 3) == 0);
  const bool nvec = ((N & 3) == 0);
  for (int k0 = 0; k0 < K; k0 += BK) {
    // Stage A tile transposed (sA: BK x BM). Vectorized path: each thread
    // loads one float4 (4 consecutive k for one row m) from global memory,
    // then scatters it into the transposed smem layout.
    if (kvec) {
      #pragma unroll
      for (int it = 0; it < (BM * (BK / 4)) / THREADS; ++it) {
        int p  = tid + it * THREADS;
        int m  = p / (BK / 4);
        int c  = p % (BK / 4);
        int gm = m0 + m;
        int gk = k0 + 4 * c;
        float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
        if (gm < M && gk < K)
          v = *reinterpret_cast<const float4*>(A + (int64_t)gm * K + gk);
        smemA[(4 * c + 0) * SA + m] = v.x;
        smemA[(4 * c + 1) * SA + m] = v.y;
        smemA[(4 * c + 2) * SA + m] = v.z;
        smemA[(4 * c + 3) * SA + m] = v.w;
      }
    } else {
      for (int idx = tid; idx < BM * BK; idx += THREADS) {
        int m  = idx / BK;
        int k  = idx % BK;
        int gm = m0 + m;
        int gk = k0 + k;
        T v = (gm < M && gk < K) ? mA(gm, gk) : T(0);
        smemA[k * SA + m] = v;
      }
    }
    // Stage B tile (BK x BN). Vectorized path: each thread performs one
    // coalesced float4 global load and one aligned float4 smem store.
    if (nvec) {
      #pragma unroll
      for (int it = 0; it < (BK * (BN / 4)) / THREADS; ++it) {
        int p  = tid + it * THREADS;
        int k  = p / (BN / 4);
        int c  = p % (BN / 4);
        int gk = k0 + k;
        int gn = n0 + 4 * c;
        float4 v = make_float4(0.f, 0.f, 0.f, 0.f);
        if (gk < K && gn < N)
          v = *reinterpret_cast<const float4*>(B + (int64_t)gk * N + gn);
        *reinterpret_cast<float4*>(&smemB[k * SB + 4 * c]) = v;
      }
    } else {
      for (int idx = tid; idx < BK * BN; idx += THREADS) {
        int k  = idx / BN;
        int n  = idx % BN;
        int gk = k0 + k;
        int gn = n0 + n;
        T v = (gk < K && gn < N) ? mB(gk, gn) : T(0);
        smemB[k * SB + n] = v;
      }
    }
    __syncthreads();
    // Each thread accumulates a contiguous 8x8 sub-tile: rows {ty*8 + i}
    // and columns {tx*8 + j}. The contiguous 8-row / 8-column ownership
    // together with the transposed sA layout lets both fragments be read
    // as two float4 loads per k step (4 LDS.128 vs 16 LDS.32 before),
    // while keeping the aligned float4 global stores in the epilogue.
    #pragma unroll
    for (int k = 0; k < BK; ++k) {
      const float4* a4 =
          reinterpret_cast<const float4*>(&smemA[k * SA + row0]);
      const float4* b4 =
          reinterpret_cast<const float4*>(&smemB[k * SB + col0]);
      float4 a0 = a4[0];
      float4 a1 = a4[1];
